use crate::i18n::Language;
use std::sync::OnceLock;

#[derive(Clone, Debug)]
pub(crate) struct Topic {
    pub id: String,
    pub title: String,
    pub body: String,
}

static EN_TOPICS: OnceLock<Vec<Topic>> = OnceLock::new();
static RU_TOPICS: OnceLock<Vec<Topic>> = OnceLock::new();

pub(crate) fn topics(language: Language) -> &'static [Topic] {
    match language {
        Language::English => EN_TOPICS.get_or_init(|| build_topics(false)),
        Language::Russian => RU_TOPICS.get_or_init(|| build_topics(true)),
    }
}

fn build_topics(russian: bool) -> Vec<Topic> {
    const IDS: [&str; 13] = [
        "supported-firmware",
        "read-write",
        "layers-modules",
        "macros-combo",
        "lighting-palettes",
        "offline-projects",
        "firmware-files",
        "backups-restore",
        "firmware-install-recovery",
        "os-layout-helper",
        "application-settings-updates",
        "connection-read-errors",
        "troubleshooting-recovery",
    ];
    let mut result: Vec<Topic> = sections(if russian {
        Language::Russian
    } else {
        Language::English
    })
    .iter()
    .zip(IDS)
    .map(|((title, body), id)| Topic {
        id: id.into(),
        title: (*title).into(),
        body: (*body).into(),
    })
    .collect();
    let catalog = crate::app::ak820_beta1_profiles::module_descriptions();
    let profiles = crate::app::ak820_beta1_profiles::profiles();
    for feature in &catalog.features {
        let supported: Vec<&str> = profiles
            .iter()
            .filter(|profile| profile.features.iter().any(|id| id == &feature.id))
            .map(|profile| profile.profile.as_str())
            .collect();
        let lang = |value: &'static crate::app::ak820_beta1_profiles::LocalizedText| {
            value.for_language(russian)
        };
        let names = if supported.is_empty() {
            if russian {
                "ни в одном профиле".to_owned()
            } else {
                "none".to_owned()
            }
        } else {
            supported.join(", ")
        };
        let body = if russian {
            format!(
                "{}\n\n{}\n\nДоступно в профилях: {}.",
                lang(&feature.summary),
                feature_steps(&feature.id, russian),
                names
            ) + &format!("\n\nОграничения: {}", lang(&feature.limits))
        } else {
            format!(
                "{}\n\n{}\n\nAvailable in profiles: {}.\n\nLimits: {}",
                lang(&feature.summary),
                feature_steps(&feature.id, russian),
                names,
                lang(&feature.limits)
            )
        };
        result.push(Topic {
            id: format!("feature-{}", feature.id),
            title: lang(&feature.title).to_owned(),
            body,
        });
    }
    result
}

fn feature_steps(id: &str, russian: bool) -> &'static str {
    let (en, ru) = match id {
        "six-layers" => ("Choose a layer at the top of Layout, then click a key to change its action. In the key picker, assign a layer action to a key when you need to reach another layer from the keyboard. Layer 0 is the base; layers 1–5 contain additional mappings. A transparent key uses the action below it; an unassigned key sends nothing. Left/Right changes the viewed layer when no text field or dialog owns input.", "Выберите слой над клавиатурой, затем нажмите на клавишу в редакторе. Чтобы переключаться между слоями с самой клавиатуры, назначьте подходящее действие слоя через выбор кода. Слой 0 — основной, слои 1–5 — дополнительные назначения. Прозрачная клавиша использует действие нижнего слоя; пустая ничего не отправляет. Стрелки влево/вправо меняют просматриваемый слой, когда фокус не находится в поле ввода или окне."),
        "sixteen-vial-macros" => ("Open Advanced → Macros, choose a slot and edit its text or sequence of key actions. Assign that macro to a key in Layout. A macro can contain press, release, tap and delay actions; only actions accepted by the current profile are offered. The sixteen slots share one storage budget. A text macro uses ASCII, so it is not a universal Unicode text expander.", "Откройте Дополнительно → Макросы, выберите запись и задайте текст или последовательность действий. Затем назначьте этот макрос клавише на вкладке Раскладка. Макрос может содержать нажатия, отпускания, одиночные нажатия и задержки; доступны только действия текущего профиля. Шестнадцать записей используют общий объём памяти. Текстовый макрос работает с ASCII и не заменяет ввод произвольного Unicode-текста."),
        "eight-two-key-combos" => ("Open Advanced → Combo. Choose a slot, two source keys and one result. Pressing the pair within the configured interval triggers the result. Configure source actions actually assigned to physical keys, and use only actions offered by the filtered picker. Adjust the common Combo interval in the supported settings if accidental triggers or missed pairs occur.", "Откройте Дополнительно → Combo. Выберите запись, две исходные клавиши и результат. Нажатие пары в пределах настроенного интервала вызывает результат. Выбирайте исходные действия, назначенные физическим клавишам, и допустимые результаты из списка. При случайных срабатываниях или пропусках проверьте общий интервал Combo в доступных настройках."),
        "compact-tap-hold" => ("Select a key and choose a dual-role action: a tap sends a key, while holding it acts as a modifier or layer switch. For example, a letter can become Ctrl while held. The firmware resolves the action using its compact timing rules. Change supported timing options on the tap/hold settings page; unavailable QMK variants are intentionally excluded.", "Выберите клавишу и назначьте двойное действие: короткое нажатие отправляет символ, удержание включает модификатор или слой. Например, буква при удержании может работать как Ctrl. Решение принимает прошивка по своим правилам и интервалу. Поддерживаемые параметры меняются на странице нажатия/удержания; отсутствующие варианты QMK не предлагаются."),
        "encoder-map" => ("On the current layer, select a rotation direction on the encoder and choose an action. Repeat for the opposite direction. Configure the encoder press through its ordinary matrix key. Each layer has its own rotation mappings. The press has no RGB LED and is not a missing color control.", "На нужном слое выберите направление вращения энкодера и назначьте действие. Повторите для противоположного направления. Нажатие энкодера настраивается как обычная клавиша матрицы. У каждого слоя свои назначения вращения. У нажатия энкодера нет светодиода RGB — отсутствие выбора цвета нормально."),
        "media-keys" => ("Select a key or encoder direction and choose an available media action, such as volume or playback. The operating system handles the resulting consumer-control event. If it has no effect in a particular player, first check the OS/player handling; assigning the action does not configure a specific application.", "Выберите клавишу или направление энкодера и назначьте доступное медиадействие, например громкость или воспроизведение. Полученное событие обрабатывает операционная система. Если конкретный плеер не реагирует, проверьте его настройки и обработку событий в ОС: назначение кода не настраивает отдельное приложение."),
        "nkro-reports" => ("This capability describes the keyboard report format. It does not by itself add an NKRO toggle to the key picker. Only profiles that also include NKRO control expose mode-changing actions. Keep the default mode unless the host requires another report format.", "Эта возможность описывает формат отчётов клавиатуры. Само её наличие не добавляет переключатель NKRO в список действий. Изменение режима доступно лишь в профилях с отдельным управлением NKRO. Оставьте основной режим, если системе не нужен другой формат отчётов."),
        "caps-word" => ("Assign the available Caps Word action to a key. Use it to type an uppercase word without keeping Shift held. It is a temporary typing mode, separate from Caps Lock and from saved mappings. Its termination rules are those of this compact firmware implementation.", "Назначьте клавише действие Caps Word. Оно позволяет набрать слово заглавными буквами без постоянного удержания Shift. Это временный режим ввода, отдельный от Caps Lock и сохранённых назначений. Условия завершения определяются компактной реализацией прошивки."),
        "repeat" => ("Assign Repeat to a key. It replays the last eligible keyboard action recorded by the firmware. It is useful for repeated letters or commands, but it is not an arbitrary macro recorder and does not repeat every service action.", "Назначьте клавише Repeat. Она повторяет последнее подходящее клавиатурное действие, запомненное прошивкой. Это удобно для повторения букв или команд, но не заменяет запись макросов и не повторяет любые служебные действия."),
        "alternate-repeat" => ("Assign Alternate Repeat when you need the opposite of a supported previous action. The opposite is selected by a fixed firmware mapping. There is no general editable dictionary in this profile; unsupported actions do not acquire an opposite automatically.", "Назначьте Alternate Repeat для выполнения обратного действия к поддерживаемому предыдущему. Соответствие выбирается из фиксированных пар прошивки. Общего редактируемого словаря здесь нет; для неподдерживаемого действия обратное автоматически не создаётся."),
        "grave-escape" => ("Assign Grave Escape to a physical key. It combines Escape with Grave according to held modifiers. Where QMK Settings advertises the related options, change those flags through settings. Check the current OS layout when the printed character differs from the key name.", "Назначьте Grave Escape физической клавише. Она объединяет Escape и Grave в зависимости от удерживаемых модификаторов. Если профиль предоставляет соответствующие параметры QMK Settings, измените их в настройках. Если напечатанный символ отличается от имени клавиши, проверьте раскладку ОС."),
        "tri-layer" => ("Assign access to layers 1 and 2 on convenient keys. Holding both activates layer 3 according to the fixed firmware arrangement. Edit layer 3 in the normal layer selector. This does not create additional layers or an arbitrary layer-combination rule.", "Назначьте доступ к слоям 1 и 2 на удобные клавиши. Одновременное включение этих слоёв активирует слой 3 по фиксированному правилу прошивки. Слой 3 редактируется обычным переключателем слоёв. Дополнительные слои и произвольные правила сочетаний не создаются."),
        "rgb-effects" => ("Open Config → RGB → Built-in. Choose an effect, then adjust the controls it supports. These effects run on the keyboard. Opening a lighting section does not start Direct playback. To return from a computer-generated effect, stop its source and select a built-in effect, or use the explicit Stop and restore effect action when available.", "Откройте Настройки → RGB → Эффекты. Выберите эффект и измените доступные для него параметры. Эти эффекты выполняет сама клавиатура. Открытие раздела не запускает Direct. Чтобы вернуться от эффекта с компьютера, остановите источник и выберите встроенный эффект либо используйте доступное действие «Остановить и вернуть эффект»."),
        "vialrgb-direct-ram" => ("Open Config → RGB → Scenes to edit colors on the physical keyboard drawing. A click selects a key, Ctrl/Cmd adds or removes a key, and Shift selects a range. Use groups for common sets. Local editing and preview do not send colors; Apply or Start explicitly sends them. Music and OpenRGB are separate source tabs. Stop retains the last sent colors; Off sends black. Save a palette or scene to a local file if it should survive restarting the application.", "Откройте Настройки → RGB → Сцены и настройте цвета на изображении клавиатуры. Щелчок выбирает клавишу, Ctrl/Cmd добавляет или убирает её, Shift выбирает диапазон. Для типовых наборов используйте группы. Редактирование и предпросмотр не отправляют цвета; это делают явные действия применения или запуска. Музыка и OpenRGB находятся в отдельных разделах. Остановка оставляет последние отправленные цвета; выключение отправляет чёрный. Для сохранения палитры или сцены после закрытия программы запишите её в локальный файл."),
        "nkro-control" => ("Assign an offered NKRO-control action to a key and invoke it when a report-mode change is needed. Changing modes clears held-key and pending-action state. The change is temporary, so it is not a permanent profile change or a saved keyboard setting.", "Назначьте клавише доступное действие управления NKRO и используйте его при необходимости сменить формат отчётов. Переключение сбрасывает удерживаемые клавиши и ожидающие действия. Изменение временное: это не смена профиля и не сохранённая настройка клавиатуры."),
        "one-shot" => ("Assign an offered One Shot modifier to a physical key. Tap it, then press the key that should receive the modifier; this avoids holding both at once. This firmware provides modifier One Shot only. Do not expect One Shot layers, timeout locking or tap-toggle behavior from the full QMK implementation.", "Назначьте физической клавише доступный одноразовый модификатор One Shot. Нажмите её, затем клавишу, к которой нужно применить модификатор: удерживать обе одновременно не требуется. Здесь реализованы только одноразовые модификаторы. Одноразовых слоёв, блокировки по тайм-ауту и tap-toggle из полного QMK нет."),
        "space-cadet" => ("Choose an offered Space Cadet action in the key picker. A tap and a hold have different roles, sharing the compact tap-hold decision path. Place it on a physical key and avoid using it as a Combo input. Verify the symbol with the OS layout used for typing.", "Выберите доступное действие Space Cadet в списке кодов. Короткое нажатие и удержание выполняют разные действия по общему компактному механизму tap-hold. Назначайте его физической клавише и не используйте входом Combo. Проверьте печатаемый символ в своей раскладке ОС."),
        "leader" => ("First configure the persistent Vial macro you want. Assign Leader to a physical key, press it, then enter one of the documented selectors 1–0 or A–F within the 300 ms window. This selects one of sixteen macros. It is a fixed macro selector, so creating an arbitrary multi-key sequence dictionary is unavailable.", "Сначала настройте нужный постоянный макрос Vial. Назначьте Leader физической клавише, нажмите её и в течение 300 мс введите один из селекторов 1–0 или A–F. Так выбирается один из шестнадцати макросов. Это фиксированный выбор макроса; создать произвольный словарь многоклавишных последовательностей нельзя."),
        "mouse-keys" => ("Assign the available cursor, wheel or mouse-button actions through the key picker. Use a separate layer for navigation if helpful. Timing and movement behavior follow the compact firmware implementation; unsupported acceleration and tuning controls are not added by the companion.", "Назначьте через список кодов доступные действия курсора, колеса или кнопок мыши. При необходимости разместите их на отдельном слое. Скорость и интервалы определяет компактная реализация прошивки; компаньон не добавляет отсутствующие режимы ускорения и настройки."),
        "auto-shift" => ("On a supporting profile, open the Auto Shift page and adjust the advertised timeout or actions. A sufficiently long press of a supported basic key produces its shifted form. It applies to the documented physical keys, not to every macro, virtual event or special keycode. The Typing profile supplies the active timeout setting.", "В поддерживающем профиле откройте Auto Shift и настройте доступный интервал или действия. Достаточно долгое удержание подходящей базовой клавиши отправляет её вариант с Shift. Механизм работает с предусмотренными физическими клавишами, а не с любыми макросами, виртуальными событиями и специальными кодами. Активная настройка интервала есть в профиле Typing."),
        "dynamic-macros" => ("Assign the available recording, stopping and playback actions. Start recording into one of the two slots, type the sequence, stop and play the slot. These recordings are short-lived RAM data. For a sequence that must survive a restart, use the persistent Vial macro editor instead.", "Назначьте доступные действия записи, остановки и воспроизведения. Начните запись в одну из двух ячеек, введите последовательность, остановите запись и запустите ячейку. Эти короткие записи находятся в ОЗУ. Если последовательность должна пережить перезапуск, используйте редактор постоянных макросов Vial."),
        "gui-lock" => ("Assign the offered GUI-lock action. Use it when accidental operating-system shortcuts are disruptive, for example during a game. It temporarily filters GUI/Windows modifier behavior; it does not erase or rewrite the saved key mappings.", "Назначьте доступное действие блокировки GUI. Используйте его, когда мешают случайные системные сочетания, например во время игры. Оно временно изменяет обработку модификатора GUI/Windows и не стирает сохранённые назначения."),
        "ctrl-gui-swap" => ("Assign the offered Ctrl/GUI swap action and invoke it to change the current session mapping. Treat it as a temporary modifier mode. It does not grant persistent Magic options or change all keyboard layouts in the operating system.", "Назначьте доступное действие обмена Ctrl/GUI и используйте его для смены поведения модификаторов в текущем сеансе. Это временный режим. Он не добавляет постоянные настройки Magic и не изменяет раскладки операционной системы."),
        "os-indicators" => ("Open Menu → OS layout indicator. Enable the helper and choose the indication for English and Russian layouts. The companion detects the supported host layout and periodically renews the firmware override. The firmware alone does not detect the OS; the helper is included in this application. Unknown layouts restore the normal indication.", "Откройте Меню → Индикатор раскладки OS. Включите помощник и выберите индикацию английской и русской раскладки. Компаньон определяет поддерживаемую раскладку системы и периодически обновляет временную индикацию прошивки. Сама прошивка не определяет ОС; помощник входит в это приложение. Неизвестная раскладка возвращает обычную индикацию."),
        "mac-pc" => ("Assign the offered Mac/PC mode action on a supporting profile. It changes the supported modifier behavior for the current session. Choose the mode yourself: it does not detect the connected host, rewrite the function row or reproduce the entire stock Mac layout.", "В подходящем профиле назначьте доступное действие режима Mac/PC. Оно меняет поддерживаемое поведение модификаторов в текущем сеансе. Режим выбирается вручную: определения компьютера, переназначения ряда F-клавиш и полного повторения штатной Mac-раскладки нет."),
        "tap-dance" => ("Open Advanced → Tap Dance on a supporting profile. Configure a slot with its tap, hold, double-tap and tap-then-hold actions and timing, then assign that slot to a key. Editing a slot alone does not assign a physical key. In offline examples, Menu → Offline module settings exposes the validated raw slot fields and explains fallback values.", "В подходящем профиле откройте Дополнительно → Tap Dance. Настройте запись: одиночное нажатие, удержание, двойное нажатие, нажатие с удержанием и интервал. Затем назначьте эту запись клавише. Настройка записи сама по себе не назначает физическую клавишу. В офлайн-примерах пункт Меню → Модули офлайн-профиля предоставляет проверяемые поля записи и поясняет резервные значения."),
        "key-overrides" => ("Open Advanced → Key Overrides. Configure a trigger key, required/forbidden modifiers, replacement action and applicable layers, then enable the row. A replacement acts only when the row conditions match. A zero row is empty. Only profile-supported rows and replacement keycodes are accepted; the firmware storage bounds are checked before a change.", "Откройте Дополнительно → Замены клавиш. Укажите исходную клавишу, необходимые и запрещённые модификаторы, действие замены и нужные слои, затем включите запись. Замена действует лишь при выполнении условий. Полностью нулевая запись пуста. Принимаются только поддерживаемые записи и коды; границы хранения проверяются перед изменением."),
        "qmk-settings" => ("Use the relevant settings pages for the options advertised by the installed profile. Changes apply through the normal checked settings flow. A value stored in a reserved area does not make an option available. Offline module settings show the active numeric IDs and ranges for an example project; those edits do not write a device.", "Используйте страницы настроек для параметров, объявленных установленным профилем. Изменения проходят обычную проверяемую запись настроек. Наличие резервной области памяти не делает параметр доступным. Модули офлайн-профиля показывают активные числовые ID и диапазоны для примера; такие изменения не записываются на устройство."),
        "nkro" => ("This capability describes the keyboard report format. It does not by itself add an NKRO toggle to the key picker. Only profiles that also include NKRO control expose mode-changing actions. Keep the default mode unless the host requires another report format.", "Эта возможность описывает формат отчётов клавиатуры. Само её наличие не добавляет переключатель NKRO в список действий. Изменение режима доступно лишь в профилях с отдельным управлением NKRO. Оставьте основной режим, если системе не нужен другой формат отчётов."),
        "vialrgb-direct" => ("Open Config → RGB → Scenes to edit colors on the physical keyboard drawing. A click selects a key, Ctrl/Cmd adds or removes a key, and Shift selects a range. Use groups for common sets. Local editing and preview do not send colors; Apply or Start explicitly sends them. Music and OpenRGB are separate source tabs. Stop retains the last sent colors; Off sends black. Save a palette or scene to a local file if it should survive restarting the application.", "Откройте Настройки → RGB → Сцены и настройте цвета на изображении клавиатуры. Щелчок выбирает клавишу, Ctrl/Cmd добавляет или убирает её, Shift выбирает диапазон. Для типовых наборов используйте группы. Редактирование и предпросмотр не отправляют цвета; это делают явные действия применения или запуска. Музыка и OpenRGB находятся в отдельных разделах. Остановка оставляет последние отправленные цвета; выключение отправляет чёрный. Для сохранения палитры или сцены после закрытия программы запишите её в локальный файл."),
        _ => ("Select the supported action in the key picker. Availability follows the installed profile.", "Выберите поддерживаемое действие в списке кодов. Доступность определяется установленным профилем."),
    };
    if russian {
        ru
    } else {
        en
    }
}

pub(crate) fn sections(language: Language) -> &'static [(&'static str, &'static str)] {
    match language {
        Language::English => EN,
        Language::Russian => RU,
    }
}

const EN: &[(&str, &str)] = &[
    ("Supported keyboard and firmware", "This desktop candidate targets the wired AK820 and the ten exact v0.6.0-beta.2 profile images. The earlier full permanent alpha.3 image remains a separate compatibility path. Connection verifies installed CODE, manifest, layout and required settings before editing.\n\nUnknown, custom, trial and mismatched images are rejected. Source and offline tests do not establish physical qualification."),
    ("Read and write settings", "Read the keyboard settings before editing. Available keys and module settings follow the verified profile. Each persistent edit checks its acknowledgement and readback; typed module edits also compare complete NVM.\n\nIf any operation fails, choose Read settings again before continuing. The application never retries a failed write automatically."),
    ("Layers and modules", "The editor supports 6 layers, 83 matrix keys and one encoder with clockwise, counter-clockwise and press mappings. Choose a layer, then select a key or encoder action; matrix, encoder, Combo and macro tap/down/up contexts have separate keycode restrictions. Optional catalog modules include NKRO report control, One Shot, Space Cadet, Leader, Dynamic Macros, Mouse Keys, Auto Shift, GUI lock, modifier swaps and OS indicators.\n\nTap Dance and Key Overrides each provide eight typed entries only in profiles with their matching schema. QMK Settings exposes active advertised IDs; QSID 4 is active only in Typing. Availability follows the exact image, not a profile title or reserved storage.\n\nInactive saved module fields are preserved. Dynamic Macros are temporary runtime recordings, not device backups."),
    ("Macros and Combo", "There are 16 macros with a total capacity of 8192 bytes. Text is ASCII; Vial macro codes 1–7 are supported. To unlock macro editing, choose Unlock, then hold Esc and Left Ctrl for 3 seconds.\n\nUnlock starts only after an explicit action. Up to eight two-key Combos are supported. Beta.2 Combo timing comes from its active setting; alpha.3 uses 40 ms."),
    ("Lighting and local palettes", "Built-in effects are Off, Solid, Breathing, Cycle all, Cycle left/right and Reactive. Direct is available in Main, Game, Mmo and Creative. The static palette remains format v1; the additional scene editor uses format v2 with up to 16 ordered/enabled layers, 82-LED masks, Solid/Gradient/Wave/Breathing/Rain, horizontal/vertical axes, opacity and 250–60000 ms periods.\n\nQuiet-hours brightness uses local wall-clock time, includes its start and excludes its end, and supports overnight intervals. A local preview and 32-state undo/redo are provided. Select by click, Ctrl/Cmd-click or Shift-click; drag selection is not supported.\n\nLive playback has a queue of one and a conservative application cap of 10 frames/s, not a hardware-qualified rate. Priority operations pause and drop pending frames; playback resumes only in the same intact session. A UI suspension over two seconds, disconnect, generation/profile change, error or physical mode/speed/HSV change stops playback without retry or restore.\n\nStop leaves sent RAM colors. Explicit Off sends one black frame only in a safe intact session. No built-in mode is automatically restored; select it explicitly.\n\nExplicit playback continues while the window is minimized or hidden in the tray and the GUI process remains alive. Quit or closing the interface into the lightweight layout helper stops RGB and capture; reopening does not restart them. There is no persistent scheduler daemon, automatic playback start, per-frame NVM save, palette getter or atomic frame commit.\n\nDirect colors remain volatile. Lighting → Music opens bundled CAVA controls for system audio or a no-capture test, with spectrum/pulse/bass, sensitivity and smoothing. Capture starts only on request, never falls back to a microphone and stops with the source.\n\nLinux uses PulseAudio or PipeWire-Pulse; Windows uses WASAPI loopback; macOS requires 14.2+ and capture permission. Receive OpenRGB offers a local SDK 0/1 endpoint at 127.0.0.1. Stop and restore effect is a separate explicit action for the actual previous built-in mode in the same intact session.\n\nCancelled in-flight frames require a new start. Screen and game integrations remain planned."),
    ("Offline projects", "Start with --demo-ak820 to edit independent examples for Main, Game, Mmo, Typing, Code, Pointer, Onehand, Creative, Shortcuts and Multios without discovering a device. Switching retains changes in memory. Save/Open project uses .ak820project.json version 2 with exact release, catalog and image identity.\n\nIt is an example project, not a device backup. Version 1 beta.1 projects require manual migration. RGB palette presets are separate files.\n\nOutside demo mode, catalog selection previews a profile and never changes installed firmware."),
    ("Firmware files", "Open Menu → Check firmware files, choose the target profile, and select three local files: prepared firmware of exactly 51,136 bytes, a complete current snapshot of 65,536 bytes, and your personal OEM recovery copy of 65,536 bytes. Choose Check files to verify that the firmware matches the profile and the snapshot is compatible with the recovery copy. Hashes and file details are available in the result.\n\nA successful check confirms the selected file contents only; it cannot confirm that the snapshot is current or came from the connected keyboard. Use Install firmware for a separate device-bound preview and explicit flash confirmation. Keep your OEM recovery copy private."),
    ("Backups and restore preview", "Open Menu → Backups and restore, choose a folder, then choose Read complete snapshot for a verified beta.2 keyboard with no pending edits. The application checks replies against saved settings. If a check fails or reading is cancelled, it stops without retry.\n\nThe complete snapshot stays in memory until you choose Save new backup; saving creates and rechecks a separate backup folder. Backup file operations support Linux, macOS and Windows with platform-specific filesystem guarantees. Restore starts from the immutable preview and requires a matching fresh complete capture, a verified safety backup and a fresh Esc + Left Ctrl three-second hold.\n\nEach whitelisted setter runs once and is checked; final full ROM and settings are verified. Errors stop without retry or automatic rollback. Read-only sessions refuse restore; stopped RGB is not resumed automatically.\n\nReset to release defaults uses the same protected restore process and keeps inactive or reserved data. Deleting an inspected backup requires a separate permanent-deletion confirmation. .entlayout is a partial editor snapshot, not a complete backup. .ak820project.json stores offline examples. RGB palettes and scenes are separate local files; volatile RGB colors are not included in the device backup."),
    ("Install firmware and OEM recovery", "Open Menu → Install firmware, explicitly select the installation device and a backup folder, and choose a bundled profile or exact supported prepared file. The bundled beta2 firmware requires prerelease opt-in. Check release status when online; cached metadata can miss a later withdrawal while offline.\n\nPreparation reads the current complete image. Preserving settings requires a verified capture and compatible transition; defaults require explicit selection. Review the hashes and settings effect, then choose Start flashing.\n\nProject images request a fresh Esc + Left Ctrl hold. A durable safety copy is saved before erase. The single attempt verifies the complete ROM; failure stops without retry or automatic recovery.\n\nSaved safety paths remain visible after failure. OEM rollback requires the original private first-capture snapshot, this application's local receipt, the same USB port and a nonempty device serial; unsupported ownership blocks rollback. Do not share OEM data.\n\nPhysical flash and recovery remain unqualified."),
    ("OS layout helper", "Open Menu → OS layout indicator, enable the OS helper and map EN/RU to normal, off, on or slow breathing. Unknown layouts release the override; unsupported Wayland compositors cannot report a layout. These preferences stay on the computer.\n\nThe helper pauses while another operation owns the device and stops refreshing after an error. Closing the interface releases the editor and keeps the enabled helper; reopen AK Configurator to return. Explicit Quit exits. --ak820-helper starts without a GUI; minimized autostart also uses the helper when enabled.\n\nThe temporary firmware indication expires within three seconds without refresh."),
    ("Application settings and updates", "Use the EN/RU selector in the top navigation to change the language immediately; the choice is remembered. F1 or ? opens this offline help, including before connection. Menu → Application settings controls the configurator on this computer, including language, appearance, scaling and update behavior. Helper preferences are available under Menu → OS layout indicator. They are separate from keyboard settings and are not included in keyboard backups. About AK Configurator → Application updates performs an explicit check.\n\nStable releases are the default; prereleases require opting in. A check or download does not install anything. The updater verifies the published six-target index, asset size and SHA256, then displays the downloaded file path and per-user installation guidance.\n\nIt never launches an installer or sends a keyboard command. SHA256 checks integrity against published metadata, not an independent publisher signature. Offline metadata may not include a later withdrawal."),
    ("Connection and read errors", "Select the wired AK820 explicitly when asked. The application permits one owner for device operations; close Vial or another configurator if it holds the HID connection, then retry using the connection control. A busy, ambiguous, unsupported or mismatched device is not edited.\n\nIf a read times out, disconnects or returns inconsistent data, the session stops and editing remains unavailable until a new read succeeds. Reconnect and inspect the device state before continuing. Errors do not trigger automatic retries.\n\nMissing optional QMK Settings support is a profile capability, not by itself a connection failure."),
    ("Troubleshooting and recovery", "If the keyboard disconnects during an operation, do not assume it succeeded: reconnect and read the state again. A failed setting write stops further changes; use Read settings again before continuing. If firmware installation fails, do not repeat the flash blindly, reset the keyboard or start an automatic rollback.\n\nKeep the displayed safety-copy paths and use the installer’s recovery checks; OEM rollback is available only when the original local ownership evidence is present. If the application will not connect, close other HID applications and retry explicitly. For local application update issues, use the shown downloaded package path and platform instructions.\n\nNever share OEM ROMs, recovery snapshots, backup folders or macros in public reports."),
];

const RU: &[(&str, &str)] = &[
    ("Поддерживаемая клавиатура и прошивка", "Эта пробная версия компаньона рассчитана на проводную AK820 и десять точных образов профилей v0.6.0-beta.2. Полная постоянная alpha.3 сохранена как отдельный путь совместимости. Перед редактированием проверяются установленный CODE, манифест, раскладка и обязательные настройки.\n\nНеизвестные, пользовательские, пробные и несовпадающие образы отклоняются. Исходники и офлайн-тесты не заменяют проверку на устройстве."),
    ("Чтение и запись настроек", "Перед редактированием прочитайте настройки клавиатуры. Доступные действия и настройки модулей определяются проверенным профилем. Сохраняемое изменение проверяет подтверждение и чтение результата; типизированные настройки дополнительно сравнивают всё NVM.\n\nПри ошибке выберите «Прочитать настройки снова». Автоматического повторения неудачной записи нет."),
    ("Слои и модули", "Редактор поддерживает 6 слоёв, 83 клавиши матрицы и один энкодер с действиями по часовой стрелке, против часовой стрелки и при нажатии. Выберите слой, затем клавишу или действие энкодера; для матрицы, энкодера, Combo и контекстов tap/down/up макросов действуют отдельные ограничения выбора кодов. Необязательные модули каталога: управление отчётами NKRO, One Shot, Space Cadet, Leader, Dynamic Macros, Mouse Keys, Auto Shift, блокировка GUI, замена модификаторов и индикаторы ОС.\n\nTap Dance и Key Overrides имеют по восемь типизированных записей только в профилях с соответствующей схемой. QMK Settings показывает активные объявленные ID; QSID 4 активен только в Typing. Доступность определяется точным образом, а не названием профиля или резервной областью.\n\nНеактивные сохранённые поля сохраняются. Dynamic Macros — временные записи сеанса, а не резервная копия устройства."),
    ("Макросы и Combo", "Доступно 16 макросов общим объёмом до 8192 байт. Текст — ASCII; поддерживаются коды макросов Vial 1–7. Для разблокировки редактирования выберите Unlock, затем удерживайте Esc и левый Ctrl 3 секунды.\n\nРазблокировка начинается только после явного действия. Поддерживается до восьми двухклавишных Combo. В beta.2 их интервал задаётся активной настройкой; в alpha.3 он равен 40 мс."),
    ("Подсветка и локальные палитры", "Встроенные эффекты: выключено, постоянный цвет, дыхание, смена цветов, волна и реакция на нажатия. Direct доступен в Main, Game, Mmo и Creative. Формат статической палитры v1 сохранён; дополнительный редактор сцен использует формат v2: до 16 упорядоченных/включаемых слоёв, маски на 82 LED, Solid/Gradient/Wave/Breathing/Rain, горизонтальная/вертикальная ось, непрозрачность и периоды 250–60000 мс.\n\nЯркость в тихие часы ограничивается по местному времени: начало включено, конец исключён, поддерживаются интервалы через полночь. Есть локальный предпросмотр и отмена/повтор на 32 состояния. Выбор — щелчком, Ctrl/Cmd или Shift; перетаскивание не поддерживается.\n\nЖивое воспроизведение использует очередь ёмкостью один и консервативный предел приложения 10 кадров/с, не квалифицированный на оборудовании. Приоритетные операции приостанавливают поток и удаляют ожидающие кадры; он возобновляется только в том же целостном сеансе. Приостановка интерфейса дольше двух секунд, отключение, смена поколения/профиля, ошибка или физическая смена режима/скорости/HSV останавливают поток без повторов и восстановления.\n\nОстановка оставляет отправленные цвета в RAM. Явный Off отправляет один чёрный кадр только в безопасном целостном сеансе. Встроенный режим автоматически не восстанавливается — выберите его явно.\n\nЯвно запущенное воспроизведение продолжается при сворачивании окна или скрытии в трей, пока работает интерфейсный процесс. Выход или закрытие интерфейса с переходом в лёгкий помощник раскладки останавливает RGB и захват; повторное открытие не запускает их заново. Нет постоянного фонового планировщика, автоматического старта, записи NVM на каждый кадр, чтения палитры или атомарной фиксации кадра.\n\nЦвета Direct временные. Блок Музыка и OpenRGB управляет встроенным CAVA: системный звук или тест без захвата, спектр/пульсация/бас, чувствительность и сглаживание. Захват начинается только явно, не переключается на микрофон и прекращается вместе с источником.\n\nLinux использует PulseAudio или PipeWire-Pulse, Windows — WASAPI loopback, macOS требует 14.2+ и разрешения. Принимать OpenRGB открывает локальный endpoint SDK 0/1 на 127.0.0.1. Остановить и вернуть эффект — отдельное явное действие для фактически прочитанного прежнего встроенного режима в том же целостном сеансе.\n\nОтменённый отправляемый кадр требует нового запуска. Экранные и игровые интеграции остаются в плане."),
    ("Офлайн-проекты", "Режим --demo-ak820 открывает независимые примеры Main, Game, Mmo, Typing, Code, Pointer, Onehand, Creative, Shortcuts и Multios без поиска устройств. При переключении изменения остаются в памяти. Сохранение и открытие проекта используют .ak820project.json версии 2 с точной идентичностью релиза, каталога и образа.\n\nЭто проект примера, а не копия устройства. Для файлов beta.1 версии 1 нужна ручная миграция. Пресеты палитры RGB сохраняются отдельно.\n\nВне деморежима выбор в каталоге показывает возможности профиля и не меняет установленную прошивку."),
    ("Файлы прошивки", "Откройте «Файлы прошивки», выберите целевой профиль и укажите три локальных файла: подготовленную прошивку ровно 51 136 байт, текущий полный снимок 65 536 байт и личную OEM-копию восстановления 65 536 байт. Нажмите «Проверить файлы», чтобы проверить соответствие прошивки профилю и совместимость снимка с копией восстановления. В результате доступны хеши и сведения о файлах.\n\nУспешная проверка подтверждает только содержимое выбранных файлов: она не подтверждает, что снимок актуален или получен с подключённой клавиатуры. Для установки откройте «Установить прошивку»: это отдельный план с проверкой подключённого устройства и явным подтверждением. Не публикуйте личную OEM-копию восстановления."),
    ("Резервные копии и предпросмотр восстановления", "Откройте «Резервные копии», выберите папку, затем нажмите «Прочитать полный снимок» для проверенной клавиатуры beta.2 без ожидающих изменений. Приложение сверяет ответы с сохранёнными настройками. Если проверка не проходит или чтение отменено, оно останавливается без повтора.\n\nПолный снимок остаётся в памяти до нажатия «Сохранить новую копию»; сохранение создаёт отдельную папку и повторно проверяет копию. Файловые операции поддерживают Linux, macOS и Windows с гарантиями конкретной платформы. Восстановление запускается из неизменяемого предпросмотра и требует совпадающего свежего полного снимка, проверенной защитной копии и нового удержания Esc + левого Ctrl три секунды.\n\nКаждая разрешённая запись выполняется один раз и проверяется; затем проверяются полный ROM и настройки. При ошибке операция останавливается без повтора и автоматического отката. Сеанс только для чтения запрещает восстановление; остановленный RGB автоматически не возобновляется.\n\nСброс к настройкам выпуска проходит через тот же защищённый процесс и сохраняет неактивные и резервные данные. Удаление просмотренной копии требует отдельного подтверждения безвозвратного удаления. .entlayout — частичный снимок редактора, а не полная копия. .ak820project.json хранит офлайн-примеры. RGB-палитры и сцены — отдельные локальные файлы; временные RGB-цвета не входят в копию устройства."),
    ("Установка прошивки и возврат OEM", "Откройте «Установить прошивку», явно выберите устройство и папку защитных копий, затем встроенный профиль или точный поддерживаемый подготовленный файл. Для встроенной beta2 нужно разрешить предварительную версию. При наличии сети проверьте статус выпуска; без сети более поздний отзыв может быть неизвестен.\n\nПодготовка читает текущий полный образ. Сохранение настроек требует проверенного снимка и совместимого перехода; настройки по умолчанию выбираются явно. Проверьте суммы и влияние на настройки, затем нажмите «Начать прошивку».\n\nДля образов проекта потребуется новое удержание Esc + левого Ctrl. До стирания сохраняется проверенная защитная копия. Единственная попытка завершается проверкой полного ROM; при ошибке нет автоматического повтора или восстановления.\n\nПути сохранённых копий остаются видимыми и при ошибке. Откат OEM требует исходного закрытого снимка первого чтения, локальной записи этого приложения, того же USB-порта и непустого серийного номера; без доказанной принадлежности откат блокируется. Не публикуйте OEM-данные.\n\nФизическая установка и восстановление ещё не квалифицированы."),
    ("Помощник раскладки OS", "Включите помощник OS и сопоставьте EN/RU обычную индикацию, выключение, включение или медленное дыхание. Неизвестная раскладка возвращает обычную индикацию; неподдерживаемый композитор Wayland не сообщает раскладку. Настройки хранятся на компьютере.\n\nПомощник уступает устройство другим операциям и прекращает обновление после ошибки. При закрытии интерфейса редактор освобождается, а включённый помощник остаётся; для возврата откройте AK Configurator снова. Явный выход завершает приложение. --ak820-helper запускает помощник без GUI; свёрнутый автозапуск тоже использует включённый помощник.\n\nБез обновления временная индикация прошивки истекает за три секунды."),
    ("Настройки приложения и обновления", "Переключатель EN/RU в верхней навигации сразу меняет язык; выбор сохраняется. F1 или ? открывает эту офлайн-справку, в том числе без клавиатуры. Меню → Настройки приложения управляет конфигуратором на этом компьютере: язык, оформление, масштаб и обновления. Параметры помощника доступны через Меню → Индикатор раскладки OS. Они не являются настройками клавиатуры и не входят в её резервные копии. Пункт «О программе → Обновления приложения» выполняет явную проверку.\n\nПо умолчанию предлагаются стабильные версии; предварительные версии требуют отдельного согласия. Проверка и загрузка ничего не устанавливают. Обновитель проверяет опубликованный индекс для шести платформ, размер и SHA256 файла, затем показывает путь и инструкции установки для пользователя.\n\nОн не запускает установщик и не отправляет команд клавиатуре. SHA256 сверяет целостность с опубликованными метаданными, но не является независимой подписью издателя. Офлайн-метаданные могут не учитывать более поздний отзыв."),
    ("Подключение и ошибки чтения", "При запросе явно выберите проводную AK820. Для операций приложение использует единственного владельца устройства; если HID занят Vial или другим конфигуратором, закройте его и повторите подключение кнопкой. Занятое, неоднозначное, неподдерживаемое устройство или образ не редактируются.\n\nПри тайм-ауте чтения, отключении или несогласованных данных сеанс прекращается, а редактирование остаётся недоступным до успешного нового чтения. Переподключитесь и заново проверьте состояние устройства. Ошибки не приводят к автоматическим повторам.\n\nОтсутствие необязательной поддержки QMK Settings — свойство профиля, а не само по себе ошибка соединения."),
    ("Диагностика и восстановление", "Если клавиатура отключилась во время операции, не считайте её успешной: подключитесь снова и перечитайте состояние. Ошибка записи настройки останавливает дальнейшие изменения; перед продолжением нажмите «Прочитать настройки снова». Если установка прошивки завершилась ошибкой, не запускайте прошивку повторно вслепую, не сбрасывайте клавиатуру и не начинайте автоматический откат.\n\nСохраните показанные пути защитных копий и используйте проверки восстановления установщика; откат OEM доступен только при наличии исходных локальных данных принадлежности. Если приложение не подключается, закройте другие HID-приложения и повторите подключение явно. При проблемах обновления используйте показанный путь загруженного пакета и инструкции платформы.\n\nНе публикуйте OEM ROM, снимки восстановления, резервные папки и макросы."),
];

#[cfg(test)]
mod topic_tests {
    use super::*;
    use std::collections::BTreeSet;

    #[test]
    fn every_beta2_feature_has_bilingual_topic_and_real_profile_list() {
        let en = topics(Language::English);
        let ru = topics(Language::Russian);
        assert_eq!(
            en.len(),
            13 + crate::app::ak820_beta1_profiles::module_descriptions()
                .features
                .len()
        );
        assert_eq!(ru.len(), en.len());
        let en_ids: BTreeSet<_> = en.iter().map(|topic| topic.id.as_str()).collect();
        let ru_ids: BTreeSet<_> = ru.iter().map(|topic| topic.id.as_str()).collect();
        assert_eq!(en_ids.len(), en.len());
        assert_eq!(en_ids, ru_ids);
        for feature in &crate::app::ak820_beta1_profiles::module_descriptions().features {
            let id = format!("feature-{}", feature.id);
            let en_topic = en.iter().find(|topic| topic.id == id).unwrap();
            let ru_topic = ru.iter().find(|topic| topic.id == id).unwrap();
            assert!(en_topic.body.contains("Available in profiles:"));
            assert!(en_topic.body.contains("Limits:"));
            assert!(ru_topic.body.contains("Доступно в профилях:"));
            assert!(ru_topic.body.contains("Ограничения:"));
            assert_ne!(en_topic.body, ru_topic.body);
        }
    }
}
